package com.acaivis.service; import com.acaivis.dto.*; import com.acaivis.exception.*; import com.acaivis.model.DeliveryZone; import com.acaivis.repository.DeliveryZoneRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class DeliveryZoneService {private final DeliveryZoneRepository repo; public DeliveryZoneService(DeliveryZoneRepository r){repo=r;} public List<DeliveryZoneResponse> findAll(){return repo.findAll().stream().map(z->new DeliveryZoneResponse(z.getId(),z.getName(),z.getFee(),z.isActive())).toList();} public DeliveryZoneResponse create(DeliveryZoneRequest d){String n=d.name().trim();if(repo.existsByNameIgnoreCase(n))throw new BusinessException("Bairro já cadastrado");DeliveryZone z=new DeliveryZone();z.setName(n);z.setFee(d.fee());return to(repo.save(z));} public DeliveryZoneResponse update(Long id,DeliveryZoneRequest d){DeliveryZone z=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Bairro não encontrado"));String n=d.name().trim();if(repo.existsByNameIgnoreCaseAndIdNot(n,id))throw new BusinessException("Bairro já cadastrado");z.setName(n);z.setFee(d.fee());return to(repo.save(z));} public void delete(Long id){DeliveryZone z=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Bairro não encontrado"));z.setActive(false);repo.save(z);} public DeliveryZoneResponse reactivate(Long id){DeliveryZone z=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Bairro não encontrado"));z.setActive(true);return to(repo.save(z));} private DeliveryZoneResponse to(DeliveryZone z){return new DeliveryZoneResponse(z.getId(),z.getName(),z.getFee(),z.isActive());}}
